<?php $pageTitle='Scheduling run comparison';$counts=array_count_values(array_column($changes,'state')); ?>
<section class="page-heading"><div><p class="eyebrow">Run comparison</p><h1>Run #<?= (int)($previous['id']??0) ?> → Run #<?= (int)$current['id'] ?></h1><p>Review placements changed by controlled regeneration.</p></div><div class="heading-actions"><a class="primary-button" href="<?= e(url('date-sheets/'.$current['cycle_id'].'/automatic/runs/'.$current['id'])) ?>"><i class="ti ti-arrow-left"></i> Back to review</a></div></section>
<?php if(!$previous):?><section class="panel validation-empty"><i class="ti ti-arrows-diff"></i><h2>No earlier generated run</h2><p>This is the first generated run for the selected school and cycle. A comparison becomes available after regeneration.</p></section><?php else:?>
<section class="run-summary"><div><span>Unchanged</span><strong><?= (int)($counts['unchanged']??0) ?></strong></div><div><span>Moved</span><strong><?= (int)($counts['moved']??0) ?></strong></div><div><span>Added</span><strong><?= (int)($counts['added']??0) ?></strong></div><div><span>Removed</span><strong><?= (int)($counts['removed']??0) ?></strong></div></section>
<section class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>Change</th><th>Programme / subject</th><th>Previous placement</th><th>Current placement</th></tr></thead><tbody><?php foreach($changes as $change):$identity=$change['after']?:$change['before'];?><tr><td><span class="change-chip <?= e($change['state']) ?>"><?= e(ucfirst($change['state'])) ?></span></td><td><strong><?= e($identity['programme_code'].' · '.$identity['course_code']) ?></strong><small class="cell-note">Semester <?= (int)$identity['semester'] ?></small></td><td><?= $change['before']?e(($change['before']['assigned_date']?:'Unscheduled').' · '.($change['before']['shift_name']?:'—')):'—' ?></td><td><?= $change['after']?e(($change['after']['assigned_date']?:'Unscheduled').' · '.($change['after']['shift_name']?:'—')):'—' ?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?>
